def discover(engine_id=None, session_id=None, program_id=None, origin=None, status=None, name_prefix=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0460000" if __import__("os").path.isdir("./environment_mix/0460000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_iso(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _is_str(x):
        return isinstance(x, str)

    def _match_id(pattern_prefix, val):
        if not isinstance(val, str):
            return False
        if not val.startswith(pattern_prefix):
            return False
        # approximate vendor pattern: ^prefix_[0-9A-Z]{18,}$
        parts = val.split("_", 1)
        if len(parts) != 2:
            return False
        suffix = parts[1]
        if len(suffix) < 18:
            return False
        for ch in suffix:
            if not ("0" <= ch <= "9" or "A" <= ch <= "Z"):
                return False
        return True

    def _log(endpoint, status_code, latency_ms, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "rqlg_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "status": status_code,
            "latency_ms": latency_ms,
            "timestamp": _now_iso(),
            "meta": meta or {},
        }
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = datetime.datetime.now(datetime.timezone.utc)

    # Validate inputs
    if engine_id is None and session_id is None:
        latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
        _log("discover", "VALIDATION_ERROR", latency, {"reason": "missing_engine_or_session"})
        return _err("VALIDATION_ERROR", "Either engine_id or session_id must be provided.")

    if engine_id is not None and not _match_id("pleng_", engine_id):
        latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
        _log("discover", "VALIDATION_ERROR", latency, {"reason": "bad_engine_id"})
        return _err("VALIDATION_ERROR", "engine_id is invalid.")

    if session_id is not None and not _match_id("plses_", session_id):
        latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
        _log("discover", "VALIDATION_ERROR", latency, {"reason": "bad_session_id"})
        return _err("VALIDATION_ERROR", "session_id is invalid.")

    if program_id is not None and not _match_id("plprg_", program_id):
        latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
        _log("discover", "VALIDATION_ERROR", latency, {"reason": "bad_program_id"})
        return _err("VALIDATION_ERROR", "program_id is invalid.")

    if origin is not None and origin not in ("builtin", "library", "user_program"):
        latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
        _log("discover", "VALIDATION_ERROR", latency, {"reason": "bad_origin"})
        return _err("VALIDATION_ERROR", "origin is invalid.")

    if status is not None and status not in ("active", "stale"):
        latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
        _log("discover", "VALIDATION_ERROR", latency, {"reason": "bad_status"})
        return _err("VALIDATION_ERROR", "status is invalid.")

    if name_prefix is not None and not _is_str(name_prefix):
        latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
        _log("discover", "VALIDATION_ERROR", latency, {"reason": "bad_name_prefix"})
        return _err("VALIDATION_ERROR", "name_prefix must be a string.")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
        _log("discover", "VALIDATION_ERROR", latency, {"reason": "bad_limit"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")

    if cursor is not None and not _is_str(cursor):
        latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
        _log("discover", "VALIDATION_ERROR", latency, {"reason": "bad_cursor"})
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    if sort is None:
        sort = "name"
    if sort not in ("name", "-name", "arity", "-arity", "updated_at", "-updated_at"):
        latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
        _log("discover", "VALIDATION_ERROR", latency, {"reason": "bad_sort"})
        return _err("VALIDATION_ERROR", "sort is invalid.")

    engines = _load("prolog_engines.json")
    sessions = _load("prolog_sessions.json")
    programs = _load("prolog_programs.json")
    entries = _load("predicate_catalog_entries.json")

    if not isinstance(engines, list) or not isinstance(sessions, list) or not isinstance(programs, list) or not isinstance(entries, list):
        latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
        _log("discover", "FAILED", latency, {"reason": "corrupt_datastore"})
        return _err("CONFLICT", "Datastore is in an invalid state.")

    # Resolve engine/session context and enforce "active engine" rule.
    sess = None
    eng = None
    if session_id is not None:
        sess = next((s for s in sessions if s.get("id") == session_id), None)
        if sess is None:
            latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
            _log("discover", "NOT_FOUND", latency, {"reason": "session_not_found"})
            return _err("NOT_FOUND", "Session not found.")
        eng = next((e for e in engines if e.get("id") == sess.get("engine_id")), None)
        if eng is None:
            latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
            _log("discover", "CONFLICT", latency, {"reason": "missing_engine_fk"})
            return _err("CONFLICT", "Session references a missing engine.")
    else:
        eng = next((e for e in engines if e.get("id") == engine_id), None)
        if eng is None:
            latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
            _log("discover", "NOT_FOUND", latency, {"reason": "engine_not_found"})
            return _err("NOT_FOUND", "Engine not found.")

    if eng.get("status") != "active":
        latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
        _log("discover", "CONFLICT", latency, {"reason": "engine_not_active", "engine_status": eng.get("status")})
        return _err("CONFLICT", "Engine is not active.")

    if program_id is not None:
        prg = next((p for p in programs if p.get("id") == program_id), None)
        if prg is None:
            latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
            _log("discover", "NOT_FOUND", latency, {"reason": "program_not_found"})
            return _err("NOT_FOUND", "Program not found.")
        if prg.get("engine_id") != eng.get("id"):
            latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
            _log("discover", "VALIDATION_ERROR", latency, {"reason": "program_engine_mismatch"})
            return _err("VALIDATION_ERROR", "program_id does not belong to the resolved engine.")
        if session_id is not None and prg.get("session_id") != session_id:
            latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
            _log("discover", "VALIDATION_ERROR", latency, {"reason": "program_session_mismatch"})
            return _err("VALIDATION_ERROR", "program_id does not belong to the provided session.")

    # Decode cursor as integer offset (opaque)
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            offset = int(raw.decode("utf-8"))
            if offset < 0:
                raise ValueError()
        except Exception:
            latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
            _log("discover", "VALIDATION_ERROR", latency, {"reason": "bad_cursor_decode"})
            return _err("VALIDATION_ERROR", "cursor is invalid.")

    # Filter per business rule:
    # engine matches active engine and (session_id is null OR session_id matches current session), status='active'
    resolved_engine_id = eng.get("id")
    allow_session_id = sess.get("id") if sess else None

    filtered = []
    for r in entries:
        if r.get("engine_id") != resolved_engine_id:
            continue
        sid = r.get("session_id")
        if sid is not None:
            if allow_session_id is None or sid != allow_session_id:
                continue
        # rule default status='active' (unless caller explicitly asks otherwise)
        if status is None:
            if r.get("status") != "active":
                continue
        else:
            if r.get("status") != status:
                continue
        if origin is not None and r.get("origin") != origin:
            continue
        if program_id is not None and r.get("program_id") != program_id:
            continue
        if name_prefix is not None:
            nm = r.get("name")
            if not isinstance(nm, str) or not nm.startswith(name_prefix):
                continue
        filtered.append(r)

    # Sort
    def _key(row):
        if sort.endswith("name"):
            return (row.get("name") or "", row.get("arity") if isinstance(row.get("arity"), int) else 0, row.get("id") or "")
        if sort.endswith("arity"):
            return (row.get("arity") if isinstance(row.get("arity"), int) else 0, row.get("name") or "", row.get("id") or "")
        # updated_at
        dt = _parse_iso(row.get("updated_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return (dt, row.get("name") or "", row.get("id") or "")

    reverse = sort.startswith("-")
    filtered.sort(key=_key, reverse=reverse)

    total = len(filtered)
    page = filtered[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("ascii").rstrip("=")

    latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
    _log("discover", "OK", latency, {"returned": len(page), "total": total})

    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

def exec(program, **_extra):
    import json, os, datetime, hashlib, base64, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0460000" if __import__("os").path.isdir("./environment_mix/0460000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return None

    def _parse_iso(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        return prefix + base64.urlsafe_b64encode(os.urandom(14)).decode("ascii").rstrip("=").upper()

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _log(status_code, meta=None):
        logs = _ensure_list(_load("request_logs.json"))
        logs.append({
            "id": "rqlg_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": "exec",
            "status": status_code,
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            "timestamp": _iso(_now()),
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    # --- Input validation (relaxed to accept vendor schema; coerce common numeric inputs) ---
    if program is None:
        _log("VALIDATION_ERROR", {"field": "program", "reason": "missing"})
        return _err("VALIDATION_ERROR", "Missing required parameter: program", field="program")

    if not isinstance(program, str):
        # Accept common "string-like" program inputs (audit shows integers were sent)
        if isinstance(program, (int, float, bool)):
            program = str(program)
        else:
            _log("VALIDATION_ERROR", {"field": "program", "reason": "type"})
            return _err("VALIDATION_ERROR", "program must be a string.", field="program")

    if len(program) < 1:
        _log("VALIDATION_ERROR", {"field": "program", "reason": "empty"})
        return _err("VALIDATION_ERROR", "program must be non-empty.", field="program")

    engines = _ensure_list(_load("prolog_engines.json"))
    sessions = _ensure_list(_load("prolog_sessions.json"))
    programs = _ensure_list(_load("prolog_programs.json"))
    predicates = _ensure_list(_load("predicate_catalog_entries.json"))

    # Choose an engine+session combination that can serve the call.
    # Ambient auth: pick any engine that is not disabled, and a session that is ready/busy? exec requires loadable state -> ready.
    # If none exists, auto-create a new session (allowed by business rule when none exists).
    now = _now()

    eligible_engines = [e for e in engines if isinstance(e, dict) and e.get("status") in ("active", "degraded")]
    if not eligible_engines:
        _log("UNAUTHORIZED", {"reason": "no_active_engine"})
        return _err("UNAUTHORIZED", "No active Prolog engine is available for this operation.")

    # Prefer an existing ready, unexpired session whose engine is eligible
    engine_by_id = {e.get("id"): e for e in eligible_engines if isinstance(e.get("id"), str)}
    chosen_session = None
    for s in sessions:
        if not isinstance(s, dict):
            continue
        eid = s.get("engine_id")
        if eid not in engine_by_id:
            continue
        st = s.get("status")
        if st != "ready":
            continue
        exp = _parse_iso(s.get("expires_at"))
        if exp is not None and exp <= now:
            continue
        chosen_session = s
        break

    chosen_engine = None

    def _engine_limits(engine_row):
        try:
            mpb = int(engine_row.get("max_program_bytes"))
            mqc = int(engine_row.get("max_query_chars"))
            ttl = int(engine_row.get("default_session_ttl_seconds"))
            return mpb, mqc, ttl
        except Exception:
            return None

    # Auto-create session if none exists
    if chosen_session is None:
        # Pick an engine with sane limits
        for e in eligible_engines:
            lim = _engine_limits(e)
            if lim is None:
                continue
            chosen_engine = e
            break
        if chosen_engine is None:
            _log("UNAUTHORIZED", {"reason": "no_engine_with_limits"})
            return _err("UNAUTHORIZED", "No usable Prolog engine is available for this operation.")
        mpb, _mqc, ttl = _engine_limits(chosen_engine)
        created = now
        expires = created + datetime.timedelta(seconds=ttl)
        new_session = {
            "id": _gen_id("plses_"),
            "engine_id": chosen_engine["id"],
            "status": "ready",
            "loaded_program_id": None,
            "last_activity_at": _iso(created),
            "expires_at": _iso(expires),
            "created_at": _iso(created),
            "updated_at": _iso(created),
        }
        sessions.append(new_session)
        chosen_session = new_session
    else:
        chosen_engine = engine_by_id.get(chosen_session.get("engine_id"))

    if not chosen_engine:
        _log("UNAUTHORIZED", {"reason": "engine_missing"})
        return _err("UNAUTHORIZED", "No usable Prolog engine is available for this operation.")

    # Enforce session lifecycle rule
    if chosen_session.get("status") == "expired":
        _log("CONFLICT", {"rule": "expired_session_cannot_exec", "session_id": chosen_session.get("id")})
        return _err("CONFLICT", "Session is expired and cannot accept exec; create/renew a session.", session_id=chosen_session.get("id"))

    if chosen_session.get("status") != "ready":
        _log("CONFLICT", {"rule": "session_not_loadable", "session_status": chosen_session.get("status"), "session_id": chosen_session.get("id")})
        return _err("CONFLICT", "Session is not in a loadable state for exec.", session_id=chosen_session.get("id"), status=chosen_session.get("status"))

    # Enforce max_program_bytes
    limits = _engine_limits(chosen_engine)
    if limits is None:
        _log("VALIDATION_ERROR", {"rule": "engine_limits_invalid", "engine_id": chosen_engine.get("id")})
        return _err("VALIDATION_ERROR", "Engine configuration is invalid; cannot validate program size.", engine_id=chosen_engine.get("id"))
    max_program_bytes, _mqc, default_ttl = limits

    try:
        prog_bytes = len(program.encode("utf-8"))
    except Exception:
        prog_bytes = len(program)

    if prog_bytes > max_program_bytes:
        _log("VALIDATION_ERROR", {"rule": "max_program_bytes", "program_bytes": prog_bytes, "max_program_bytes": max_program_bytes})
        return _err("VALIDATION_ERROR", "Program exceeds engine max_program_bytes.", rule="max_program_bytes", program_bytes=prog_bytes, max_program_bytes=max_program_bytes)

    # Dedup within a session by source_sha256 unique(session_id, source_sha256)
    sha = hashlib.sha256(program.encode("utf-8")).hexdigest()
    existing = None
    for p in programs:
        if isinstance(p, dict) and p.get("session_id") == chosen_session["id"] and p.get("source_sha256") == sha:
            existing = p
            break

    # If already loaded, be idempotent: refresh session activity and return existing program record
    def _cap_expires(session_row, engine_row, base_now):
        # sliding TTL: extend to min(base_now + ttl, created_at + ttl)
        created_at = _parse_iso(session_row.get("created_at")) or base_now
        hard_cap = created_at + datetime.timedelta(seconds=int(engine_row.get("default_session_ttl_seconds")))
        proposed = base_now + datetime.timedelta(seconds=int(engine_row.get("default_session_ttl_seconds")))
        return min(proposed, hard_cap)

    if existing and existing.get("compile_status") == "loaded":
        # update session pointers/ttl and persist
        chosen_session["loaded_program_id"] = existing.get("id")
        chosen_session["last_activity_at"] = _iso(now)
        chosen_session["expires_at"] = _iso(_cap_expires(chosen_session, chosen_engine, now))
        chosen_session["updated_at"] = _iso(now)
        _save("prolog_sessions.json", sessions)
        _log("OK", {"idempotent": True, "program_id": existing.get("id"), "session_id": chosen_session.get("id")})
        return {"program": existing, "session": chosen_session}

    # Create program row and transition queued -> compiling -> loaded|error
    pid = _gen_id("plprg_")
    created_at = now
    prog_row = {
        "id": pid,
        "engine_id": chosen_engine["id"],
        "session_id": chosen_session["id"],
        "source_text": program,
        "source_sha256": sha,
        "compile_status": "queued",
        "compile_error": None,
        "loaded_predicates_cache": None,
        "created_at": _iso(created_at),
        "updated_at": _iso(created_at),
    }
    programs.append(prog_row)

    # queued -> compiling
    prog_row["compile_status"] = "compiling"
    prog_row["updated_at"] = _iso(_now())

    # Minimal "compiler": treat certain tokens as syntax error to drive realistic transitions
    src = program
    compile_error = None
    if re.search(r"(^|\s)\?-\s", src):
        compile_error = "ERROR: Query directive '?-' is not allowed in program source."
    elif "SYNTAX_ERROR" in src:
        compile_error = "ERROR: Syntax error."
    elif len(src.strip()) == 0:
        compile_error = "ERROR: Empty program."
    # otherwise loaded

    if compile_error:
        # compiling -> error
        prog_row["compile_status"] = "error"
        prog_row["compile_error"] = compile_error
        prog_row["updated_at"] = _iso(_now())
        # Session activity not updated on failed exec; keep as-is
        _save("prolog_programs.json", programs)
        _save("prolog_sessions.json", sessions)
        _log("OK", {"program_id": pid, "session_id": chosen_session["id"], "compile_status": "error"})
        return {"program": prog_row, "session": chosen_session}

    # compiling -> loaded
    prog_row["compile_status"] = "loaded"
    prog_row["compile_error"] = None
    prog_row["updated_at"] = _iso(_now())

    # Update session loaded_program_id and activity; extend expires_at with cap
    chosen_session["loaded_program_id"] = pid
    chosen_session["last_activity_at"] = _iso(_now())
    chosen_session["expires_at"] = _iso(_cap_expires(chosen_session, chosen_engine, _now()))
    chosen_session["updated_at"] = _iso(_now())

    # Predicate catalog update rule: mark old user_program entries stale, add/refresh entries derived from new program.
    # Derivation: scan for "name/arity" patterns like foo(A,B). This is heuristic but persists changes.
    sid = chosen_session["id"]
    eid = chosen_engine["id"]

    for ent in predicates:
        if isinstance(ent, dict) and ent.get("session_id") == sid and ent.get("origin") == "user_program" and ent.get("status") == "active":
            ent["status"] = "stale"
            ent["updated_at"] = _iso(_now())

    found = set()
    for m in re.finditer(r"^\s*([a-z][a-zA-Z0-9_]*)\s*\(([^)]*)\)\s*[:.-]", program, flags=re.M):
        name = m.group(1)
        args = m.group(2).strip()
        if args == "":
            arity = 0
        else:
            # naive comma count
            arity = 1 + args.count(",")
        if 0 <= arity <= 255:
            found.add((name, arity))

    # Ensure at least one predicate for a non-empty program: if none found, keep cache empty (no requirement to create)
    now2 = _now()
    for name, arity in sorted(found):
        sig = f"{name}/{arity}"
        # unique(engine_id, session_id, program_id, signature)
        existing_ent = None
        for ent in predicates:
            if isinstance(ent, dict) and ent.get("engine_id") == eid and ent.get("session_id") == sid and ent.get("program_id") == pid and ent.get("signature") == sig:
                existing_ent = ent
                break
        if existing_ent:
            existing_ent["status"] = "active"
            existing_ent["updated_at"] = _iso(now2)
        else:
            predicates.append({
                "id": _gen_id("plpred_"),
                "engine_id": eid,
                "session_id": sid,
                "program_id": pid,
                "name": name,
                "arity": arity,
                "signature": sig,
                "origin": "user_program",
                "is_dynamic": False,
                "documentation": None,
                "status": "active",
                "created_at": _iso(now2),
                "updated_at": _iso(now2),
            })

    # persist
    _save("prolog_sessions.json", sessions)
    _save("prolog_programs.json", programs)
    _save("predicate_catalog_entries.json", predicates)

    _log("OK", {"program_id": pid, "session_id": chosen_session["id"], "compile_status": "loaded"})
    return {"program": prog_row, "session": chosen_session}

def query(query, **_extra):
    import json, os, datetime, base64, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0460000" if __import__("os").path.isdir("./environment_mix/0460000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return None

    def _parse_iso(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        return prefix + base64.urlsafe_b64encode(os.urandom(14)).decode("ascii").rstrip("=").upper()

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _log(status_code, meta=None):
        logs = _ensure_list(_load("request_logs.json"))
        logs.append({
            "id": "rqlg_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": "query",
            "status": status_code,
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            "timestamp": _iso(_now()),
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    # Validate / coerce
    if query is None:
        _log("VALIDATION_ERROR", {"field": "query", "reason": "missing"})
        return _err("VALIDATION_ERROR", "Missing required parameter: query", field="query")

    if not isinstance(query, str):
        # Audit shows integer passed; accept by coercion
        if isinstance(query, (int, float, bool)):
            query = str(query)
        else:
            _log("VALIDATION_ERROR", {"field": "query", "reason": "type"})
            return _err("VALIDATION_ERROR", "query must be a string.", field="query")

    if len(query) < 1:
        _log("VALIDATION_ERROR", {"field": "query", "reason": "empty"})
        return _err("VALIDATION_ERROR", "query must be non-empty.", field="query")

    engines = _ensure_list(_load("prolog_engines.json"))
    sessions = _ensure_list(_load("prolog_sessions.json"))
    programs = _ensure_list(_load("prolog_programs.json"))
    queries = _ensure_list(_load("prolog_queries.json"))

    now = _now()

    eligible_engines = [e for e in engines if isinstance(e, dict) and e.get("status") in ("active", "degraded")]
    if not eligible_engines:
        _log("UNAUTHORIZED", {"reason": "no_active_engine"})
        return _err("UNAUTHORIZED", "No active Prolog engine is available for this operation.")

    engine_by_id = {e.get("id"): e for e in eligible_engines if isinstance(e.get("id"), str)}

    # Find a session that is ready (or busy?) for querying. We'll require ready; if busy, conflict.
    chosen_session = None
    chosen_engine = None
    for s in sessions:
        if not isinstance(s, dict):
            continue
        eid = s.get("engine_id")
        if eid not in engine_by_id:
            continue
        exp = _parse_iso(s.get("expires_at"))
        if exp is not None and exp <= now:
            continue
        if s.get("status") in ("ready", "busy"):
            chosen_session = s
            chosen_engine = engine_by_id[eid]
            break

    # Auto-create session if none exists (allowed)
    if chosen_session is None:
        # create session on a sane engine
        def _engine_limits(e):
            try:
                return int(e.get("max_program_bytes")), int(e.get("max_query_chars")), int(e.get("default_session_ttl_seconds"))
            except Exception:
                return None
        engine = None
        for e in eligible_engines:
            if _engine_limits(e) is not None:
                engine = e
                break
        if engine is None:
            _log("UNAUTHORIZED", {"reason": "no_engine_with_limits"})
            return _err("UNAUTHORIZED", "No usable Prolog engine is available for this operation.")
        _mpb, _mqc, ttl = _engine_limits(engine)
        created = now
        expires = created + datetime.timedelta(seconds=ttl)
        chosen_session = {
            "id": _gen_id("plses_"),
            "engine_id": engine["id"],
            "status": "ready",
            "loaded_program_id": None,
            "last_activity_at": _iso(created),
            "expires_at": _iso(expires),
            "created_at": _iso(created),
            "updated_at": _iso(created),
        }
        sessions.append(chosen_session)
        chosen_engine = engine

    # Session must not be expired
    if chosen_session.get("status") == "expired":
        _log("CONFLICT", {"rule": "expired_session_cannot_query", "session_id": chosen_session.get("id")})
        return _err("CONFLICT", "Session is expired and cannot accept query; create/renew a session.", session_id=chosen_session.get("id"))

    # Must be queryable state
    if chosen_session.get("status") != "ready":
        _log("CONFLICT", {"rule": "session_not_queryable", "session_status": chosen_session.get("status"), "session_id": chosen_session.get("id")})
        return _err("CONFLICT", "Session is not in a queryable state.", session_id=chosen_session.get("id"), status=chosen_session.get("status"))

    # Need loaded program
    program_id = chosen_session.get("loaded_program_id")
    if not program_id:
        _log("CONFLICT", {"rule": "no_loaded_program", "session_id": chosen_session.get("id")})
        return _err("CONFLICT", "No program is loaded in the active session; call exec first.", session_id=chosen_session.get("id"))

    program_row = None
    for p in programs:
        if isinstance(p, dict) and p.get("id") == program_id:
            program_row = p
            break
    if not program_row:
        _log("CONFLICT", {"rule": "loaded_program_missing", "session_id": chosen_session.get("id"), "program_id": program_id})
        return _err("CONFLICT", "Loaded program reference is missing; call exec again.", session_id=chosen_session.get("id"), program_id=program_id)
    if program_row.get("compile_status") != "loaded":
        _log("CONFLICT", {"rule": "program_not_loaded", "program_status": program_row.get("compile_status"), "program_id": program_id})
        return _err("CONFLICT", "Loaded program is not in 'loaded' state.", program_id=program_id, compile_status=program_row.get("compile_status"))

    # Enforce max_query_chars
    try:
        max_query_chars = int(chosen_engine.get("max_query_chars"))
    except Exception:
        _log("VALIDATION_ERROR", {"rule": "engine_limits_invalid", "engine_id": chosen_engine.get("id")})
        return _err("VALIDATION_ERROR", "Engine configuration is invalid; cannot validate query length.", engine_id=chosen_engine.get("id"))
    if len(query) > max_query_chars:
        _log("VALIDATION_ERROR", {"rule": "max_query_chars", "query_chars": len(query), "max_query_chars": max_query_chars})
        return _err("VALIDATION_ERROR", "Query exceeds engine max_query_chars.", rule="max_query_chars", query_chars=len(query), max_query_chars=max_query_chars)

    # Create query row and transition queued -> running -> succeeded|failed
    qid = _gen_id("plqry_")
    created_at = _now()
    qrow = {
        "id": qid,
        "engine_id": chosen_engine["id"],
        "session_id": chosen_session["id"],
        "program_id": program_id,
        "query_text": query,
        "status": "queued",
        "result_format": "json_bindings",
        "result_payload": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "duration_ms": None,
        "created_at": _iso(created_at),
        "updated_at": _iso(created_at),
    }
    queries.append(qrow)

    # queued -> running
    started = _now()
    qrow["status"] = "running"
    qrow["started_at"] = _iso(started)
    qrow["updated_at"] = _iso(started)

    # "Run" query: heuristic outcomes
    fail_msg = None
    qtxt = query.strip()
    if re.search(r"(^|\s)\?-\s", qtxt):
        fail_msg = "Syntax error: Operator expected near `?-`"
    elif "undefined" in qtxt.lower() or "nonexistent_predicate" in qtxt.lower():
        fail_msg = "Undefined procedure."
    elif qtxt.endswith(".") is False:
        # Many Prolog queries require trailing '.'
        # treat as failure but still a service response
        fail_msg = "Syntax error: Query must end with '.'"
    elif "fail" == qtxt.strip(". ").lower():
        # boolean false
        qrow["result_format"] = "boolean"
        qrow["result_payload"] = {"success": False}
    else:
        # succeed with a simple placeholder binding/boolean
        if re.search(r"\btrue\b", qtxt.strip(". ").lower()):
            qrow["result_format"] = "boolean"
            qrow["result_payload"] = {"success": True}
        else:
            # json_bindings
            qrow["result_format"] = "json_bindings"
            qrow["result_payload"] = {"solutions": [{"_": "ok"}], "truncated": False}

    finished = _now()
    duration_ms = int(max(0, (finished - started).total_seconds() * 1000))
    qrow["finished_at"] = _iso(finished)
    qrow["duration_ms"] = duration_ms

    if fail_msg:
        qrow["status"] = "failed"
        qrow["error_message"] = fail_msg
        qrow["result_payload"] = None
    else:
        qrow["status"] = "succeeded"
        qrow["error_message"] = None
        if qrow["result_payload"] is None:
            # enforce rule: succeeded must have payload
            qrow["result_payload"] = {"solutions": [], "truncated": False}

    qrow["updated_at"] = _iso(finished)

    # Update session last_activity and sliding TTL cap (created_at + default_ttl)
    def _cap_expires(session_row, engine_row, base_now):
        created_dt = _parse_iso(session_row.get("created_at")) or base_now
        ttl = int(engine_row.get("default_session_ttl_seconds"))
        hard_cap = created_dt + datetime.timedelta(seconds=ttl)
        proposed = base_now + datetime.timedelta(seconds=ttl)
        return min(proposed, hard_cap)

    chosen_session["last_activity_at"] = _iso(finished)
    chosen_session["expires_at"] = _iso(_cap_expires(chosen_session, chosen_engine, finished))
    chosen_session["updated_at"] = _iso(finished)

    # Persist
    _save("prolog_sessions.json", sessions)
    _save("prolog_queries.json", queries)

    _log("OK", {"query_id": qid, "session_id": chosen_session.get("id"), "status": qrow.get("status")})
    return {"query": qrow, "session": chosen_session}

def engines(status=None, engine_type=None, name_prefix=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0460000" if __import__("os").path.isdir("./environment_mix/0460000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_iso(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(endpoint, status_code, latency_ms, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "rqlg_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "status": status_code,
            "latency_ms": latency_ms,
            "timestamp": _now_iso(),
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    t0 = datetime.datetime.now(datetime.timezone.utc)

    # Validate
    if status is not None and status not in ("active", "degraded", "disabled"):
        latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
        _log("engines", "VALIDATION_ERROR", latency, {"reason": "bad_status"})
        return _err("VALIDATION_ERROR", "status is invalid.")

    # Tool schema lists types that do not match stored enum; accept vendor values but map.
    mapping = {
        "swi_prolog": "swipl",
        "trealla": "trealla",
        "xsb": None,
        "gnu_prolog": None,
    }
    mapped_engine_type = None
    if engine_type is not None:
        if engine_type not in mapping:
            latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
            _log("engines", "VALIDATION_ERROR", latency, {"reason": "bad_engine_type"})
            return _err("VALIDATION_ERROR", "engine_type is invalid.")
        mapped_engine_type = mapping[engine_type]

    if name_prefix is not None and not isinstance(name_prefix, str):
        latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
        _log("engines", "VALIDATION_ERROR", latency, {"reason": "bad_name_prefix"})
        return _err("VALIDATION_ERROR", "name_prefix must be a string.")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
        _log("engines", "VALIDATION_ERROR", latency, {"reason": "bad_limit"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")

    if cursor is not None and not isinstance(cursor, str):
        latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
        _log("engines", "VALIDATION_ERROR", latency, {"reason": "bad_cursor"})
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    if sort is None:
        sort = "name"
    if sort not in ("name", "-name", "status", "-status", "created_at", "-created_at", "updated_at", "-updated_at"):
        latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
        _log("engines", "VALIDATION_ERROR", latency, {"reason": "bad_sort"})
        return _err("VALIDATION_ERROR", "sort is invalid.")

    # Ambient authentication: if caller can reach this tool, treat as authenticated,
    # but require that at least one engine exists, else refuse as UNAUTHORIZED per description.
    engs = _load("prolog_engines.json")
    if not isinstance(engs, list):
        latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
        _log("engines", "FAILED", latency, {"reason": "corrupt_datastore"})
        return _err("CONFLICT", "Datastore is in an invalid state.")
    if len(engs) == 0:
        latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
        _log("engines", "UNAUTHORIZED", latency, {"reason": "no_engines"})
        return _err("UNAUTHORIZED", "Caller is not authenticated.")

    # Decode cursor offset
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            offset = int(raw.decode("utf-8"))
            if offset < 0:
                raise ValueError()
        except Exception:
            latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
            _log("engines", "VALIDATION_ERROR", latency, {"reason": "bad_cursor_decode"})
            return _err("VALIDATION_ERROR", "cursor is invalid.")

    # Filter
    filtered = []
    for e in engs:
        if status is not None and e.get("status") != status:
            continue
        if mapped_engine_type is not None:
            if e.get("engine_type") != mapped_engine_type:
                continue
        elif engine_type in ("xsb", "gnu_prolog"):
            # no rows can match unsupported mapping
            continue
        if name_prefix is not None:
            nm = e.get("name")
            if not isinstance(nm, str) or not nm.startswith(name_prefix):
                continue
        filtered.append(e)

    # Sort
    def _key(row):
        if sort.endswith("name"):
            return (row.get("name") or "", row.get("id") or "")
        if sort.endswith("status"):
            return (row.get("status") or "", row.get("name") or "", row.get("id") or "")
        if sort.endswith("created_at"):
            dt = _parse_iso(row.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
            return (dt, row.get("id") or "")
        dt = _parse_iso(row.get("updated_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return (dt, row.get("id") or "")

    reverse = sort.startswith("-")
    filtered.sort(key=_key, reverse=reverse)

    total = len(filtered)
    page = filtered[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("ascii").rstrip("=")

    latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
    _log("engines", "OK", latency, {"returned": len(page), "total": total})

    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

def get_engine(engine_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0460000" if __import__("os").path.isdir("./environment_mix/0460000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    req_log_name = "request_logs.json"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_id=None, meta=None):
        logs = _load(req_log_name)
        row = {
            "id": f"rqlg_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.urandom(6).hex()}",
            "endpoint": "get_engine",
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            "ts": _now(),
            "meta": meta or {}
        }
        if isinstance(logs, list):
            logs.append(row)
            _save(req_log_name, logs)

    # Validate
    if not isinstance(engine_id, str):
        _log("VALIDATION_ERROR", meta={"field": "engine_id"})
        return _err("VALIDATION_ERROR", "engine_id must be a string", field="engine_id")
    if not re.match(r"^pleng_[0-9A-Z]{18,}$", engine_id):
        _log("VALIDATION_ERROR", meta={"field": "engine_id"})
        return _err("VALIDATION_ERROR", "engine_id is invalid", field="engine_id")

    engines = _load("prolog_engines.json")
    eng = next((e for e in engines if isinstance(e, dict) and e.get("id") == engine_id), None)
    if not eng:
        _log("NOT_FOUND", meta={"engine_id": engine_id})
        return _err("NOT_FOUND", "Engine not found", engine_id=engine_id)

    _log("OK", meta={"engine_id": engine_id})
    return {"engine": eng}

def create_session(engine_id, ttl_seconds=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0460000" if __import__("os").path.isdir("./environment_mix/0460000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    req_log_name = "request_logs.json"

    def _now_dt():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _iso(dt):
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(status_code, credential_id=None, meta=None):
        logs = _load(req_log_name)
        row = {
            "id": f"rqlg_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.urandom(6).hex()}",
            "endpoint": "create_session",
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            "ts": _iso(_now_dt()),
            "meta": meta or {}
        }
        if isinstance(logs, list):
            logs.append(row)
            _save(req_log_name, logs)

    # Validate inputs
    if not isinstance(engine_id, str):
        _log("VALIDATION_ERROR", meta={"field": "engine_id"})
        return _err("VALIDATION_ERROR", "engine_id must be a string", field="engine_id")
    if not re.match(r"^pleng_[0-9A-Z]{18,}$", engine_id):
        _log("VALIDATION_ERROR", meta={"field": "engine_id"})
        return _err("VALIDATION_ERROR", "engine_id is invalid", field="engine_id")

    if ttl_seconds is not None:
        if not isinstance(ttl_seconds, int):
            _log("VALIDATION_ERROR", meta={"field": "ttl_seconds"})
            return _err("VALIDATION_ERROR", "ttl_seconds must be an integer", field="ttl_seconds")
        if ttl_seconds < 1 or ttl_seconds > 86400:
            _log("VALIDATION_ERROR", meta={"field": "ttl_seconds"})
            return _err("VALIDATION_ERROR", "ttl_seconds out of range", field="ttl_seconds", minimum=1, maximum=86400)

    engines = _load("prolog_engines.json")
    eng = next((e for e in engines if isinstance(e, dict) and e.get("id") == engine_id), None)
    if not eng:
        _log("NOT_FOUND", meta={"engine_id": engine_id})
        return _err("NOT_FOUND", "Engine not found", engine_id=engine_id)

    if eng.get("status") == "disabled":
        _log("CONFLICT", meta={"engine_id": engine_id, "engine_status": eng.get("status")})
        return _err("CONFLICT", "Engine is disabled", engine_id=engine_id)

    # Determine TTL cap behavior:
    # - Engine has default_session_ttl_seconds; session expiry must not exceed created_at + default_session_ttl_seconds.
    # - ttl_seconds param is a request, capped by engine default policy (and tool schema max).
    try:
        default_ttl = int(eng.get("default_session_ttl_seconds"))
    except Exception:
        _log("VALIDATION_ERROR", meta={"engine_id": engine_id})
        return _err("VALIDATION_ERROR", "Engine default_session_ttl_seconds is invalid", engine_id=engine_id)

    if default_ttl < 60 or default_ttl > 86400:
        _log("VALIDATION_ERROR", meta={"engine_id": engine_id})
        return _err("VALIDATION_ERROR", "Engine default_session_ttl_seconds out of allowed range", engine_id=engine_id)

    requested = ttl_seconds if ttl_seconds is not None else default_ttl
    # cap by engine default_ttl (max lifetime cap) and also by 86400 by input constraints
    effective_ttl = min(max(1, requested), default_ttl)

    now = _now_dt()
    created_at = now
    expires_at = created_at + datetime.timedelta(seconds=effective_ttl)

    sessions = _load("prolog_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    # generate id plses_[0-9A-Z]{18,}
    def _gen_id(prefix):
        # 18 chars base32-ish uppercase; use hex then map to base32 alphabet
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        raw = os.urandom(16)
        acc = 0
        bits = 0
        out = []
        for b in raw:
            acc = (acc << 8) | b
            bits += 8
            while bits >= 5 and len(out) < 22:
                bits -= 5
                out.append(alphabet[(acc >> bits) & 31])
        while len(out) < 18:
            out.append(alphabet[os.urandom(1)[0] & 31])
        return prefix + "".join(out[:22])

    sid = _gen_id("plses_")
    session = {
        "id": sid,
        "engine_id": engine_id,
        "status": "ready",
        "loaded_program_id": None,
        "last_activity_at": _iso(now),
        "expires_at": _iso(expires_at),
        "created_at": _iso(created_at),
        "updated_at": _iso(now),
    }
    sessions.append(session)
    _save("prolog_sessions.json", sessions)

    _log("OK", meta={"engine_id": engine_id, "session_id": sid, "ttl_seconds": effective_ttl})
    return {"session": session}

def get_session(session_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0460000" if __import__("os").path.isdir("./environment_mix/0460000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    req_log_name = "request_logs.json"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_id=None, meta=None):
        logs = _load(req_log_name)
        row = {
            "id": f"rqlg_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.urandom(6).hex()}",
            "endpoint": "get_session",
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            "ts": _now(),
            "meta": meta or {}
        }
        if isinstance(logs, list):
            logs.append(row)
            _save(req_log_name, logs)

    # Validate
    if not isinstance(session_id, str):
        _log("VALIDATION_ERROR", meta={"field": "session_id"})
        return _err("VALIDATION_ERROR", "session_id must be a string", field="session_id")
    if not re.match(r"^plses_[0-9A-Z]{18,}$", session_id):
        _log("VALIDATION_ERROR", meta={"field": "session_id"})
        return _err("VALIDATION_ERROR", "session_id is invalid", field="session_id")

    sessions = _load("prolog_sessions.json")
    ses = next((s for s in sessions if isinstance(s, dict) and s.get("id") == session_id), None)
    if not ses:
        _log("NOT_FOUND", meta={"session_id": session_id})
        return _err("NOT_FOUND", "Session not found", session_id=session_id)

    _log("OK", meta={"session_id": session_id})
    return {"session": ses}

def renew_session(session_id, ttl_seconds=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0460000" if __import__("os").path.isdir("./environment_mix/0460000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return None

    def _parse_iso(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _ensure_list(x):
        return x if isinstance(x, list) else (x.get("rows") if isinstance(x, dict) and isinstance(x.get("rows"), list) else [])

    def _save_rows(filename, rows):
        # Store as plain list (most collections) OR preserve {"rows":[...]} shape if it exists.
        existing = _load(filename)
        if isinstance(existing, dict) and "rows" in existing:
            existing["rows"] = rows
            _save(filename, existing)
        else:
            _save(filename, rows)

    def _get_rows(filename):
        return _ensure_list(_load(filename))

    def _log(status_code, meta=None):
        # Request logs collection may or may not exist; create if absent.
        logs = _get_rows("request_logs.json")
        logs.append({
            "id": "rqlg_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + "_" + os.urandom(6).hex(),
            "endpoint": "renew_session",
            "status": status_code,
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            "timestamp": _iso(_now()),
            "meta": meta or {},
        })
        _save_rows("request_logs.json", logs)

    # ---- Validate inputs (tool schema) ----
    if not isinstance(session_id, str):
        _log("VALIDATION_ERROR", {"field": "session_id"})
        return _err("VALIDATION_ERROR", "session_id must be a string", field="session_id")
    if not re.match(r"^plses_[0-9A-Z]{18,}$", session_id):
        _log("VALIDATION_ERROR", {"field": "session_id"})
        return _err("VALIDATION_ERROR", "session_id is invalid", field="session_id")

    if ttl_seconds is not None:
        if not isinstance(ttl_seconds, int):
            _log("VALIDATION_ERROR", {"field": "ttl_seconds"})
            return _err("VALIDATION_ERROR", "ttl_seconds must be an integer", field="ttl_seconds")
        if ttl_seconds < 1 or ttl_seconds > 86400:
            _log("VALIDATION_ERROR", {"field": "ttl_seconds"})
            return _err("VALIDATION_ERROR", "ttl_seconds out of range", field="ttl_seconds", minimum=1, maximum=86400)

    # Default: if ttl_seconds omitted, renew by engine default TTL (common API behavior)
    sessions = _get_rows("prolog_sessions.json")
    sess_idx = None
    session = None
    for i, s in enumerate(sessions):
        if isinstance(s, dict) and s.get("id") == session_id:
            sess_idx = i
            session = s
            break
    if session is None:
        _log("NOT_FOUND", {"session_id": session_id})
        return _err("NOT_FOUND", "Session not found", session_id=session_id)

    # Parse required timestamps
    created_at = _parse_iso(session.get("created_at"))
    updated_at = _parse_iso(session.get("updated_at"))
    last_activity_at = _parse_iso(session.get("last_activity_at"))
    expires_at = _parse_iso(session.get("expires_at"))
    if created_at is None or expires_at is None:
        _log("VALIDATION_ERROR", {"session_id": session_id})
        return _err("VALIDATION_ERROR", "Session has invalid timestamps and cannot be renewed", session_id=session_id, rule="invalid_session_timestamps")

    engine_id = session.get("engine_id")
    if not isinstance(engine_id, str) or not engine_id:
        _log("VALIDATION_ERROR", {"session_id": session_id})
        return _err("VALIDATION_ERROR", "Session has invalid engine_id", session_id=session_id, rule="invalid_engine_id")

    engines = _get_rows("prolog_engines.json")
    engine = None
    for e in engines:
        if isinstance(e, dict) and e.get("id") == engine_id:
            engine = e
            break
    if engine is None:
        _log("NOT_FOUND", {"engine_id": engine_id, "session_id": session_id})
        return _err("NOT_FOUND", "Engine not found for session", engine_id=engine_id, session_id=session_id)

    # Validate engine constraints used by renewal logic
    default_ttl = engine.get("default_session_ttl_seconds")
    if not isinstance(default_ttl, int) or default_ttl < 60 or default_ttl > 86400:
        _log("VALIDATION_ERROR", {"engine_id": engine_id})
        return _err("VALIDATION_ERROR", "Engine has invalid default_session_ttl_seconds", engine_id=engine_id, rule="invalid_engine_default_ttl")

    # Enforce lifecycle rule: refuse renew when status == expired
    status = session.get("status")
    if status == "expired":
        _log("CONFLICT", {"session_id": session_id, "rule": "cannot_renew_expired"})
        return _err("CONFLICT", "Cannot renew an expired session; create a new session.", rule="cannot_renew_expired", session_id=session_id)

    # Compute new expiration with sliding TTL and cap at created_at + default_ttl
    now = _now()

    # If already past expires_at but status isn't expired, treat as expired for renewal.
    if expires_at <= now:
        _log("CONFLICT", {"session_id": session_id, "rule": "cannot_renew_expired"})
        return _err("CONFLICT", "Cannot renew an expired session; create a new session.", rule="cannot_renew_expired", session_id=session_id)

    add_seconds = ttl_seconds if ttl_seconds is not None else default_ttl

    cap = created_at + datetime.timedelta(seconds=default_ttl)
    proposed = expires_at + datetime.timedelta(seconds=add_seconds)

    if proposed > cap:
        _log("VALIDATION_ERROR", {"session_id": session_id, "rule": "ttl_cap_exceeded", "cap_expires_at": _iso(cap), "proposed_expires_at": _iso(proposed)})
        return _err(
            "VALIDATION_ERROR",
            "Requested renewal exceeds maximum allowed session TTL for this engine.",
            rule="ttl_cap_exceeded",
            session_id=session_id,
            engine_id=engine_id,
            cap_expires_at=_iso(cap),
            proposed_expires_at=_iso(proposed),
            default_session_ttl_seconds=default_ttl
        )

    # Persist update
    session = dict(session)
    session["expires_at"] = _iso(proposed)
    # Renewal counts as activity
    session["last_activity_at"] = _iso(max(last_activity_at or created_at, now))
    session["updated_at"] = _iso(now)

    sessions[sess_idx] = session
    _save_rows("prolog_sessions.json", sessions)

    _log("OK", {"session_id": session_id, "engine_id": engine_id})

    return {
        "session": session
    }
